      <a href="/" class="logo" aria-label="Aura Home">AURA</a>
      <nav class="main-nav" aria-label="Main Navigation">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
        </ul>
      </nav>
      <button class="cart-btn" aria-label="Shopping Cart, 0 items">
        <svg class="cart-icon" aria-hidden="true" viewBox="0 0 24 24">
          <path d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zM1 2v2h2l3.6 7.59-1.35 2.45c-.16.28-.25.61-.25.96 0 1.1.9 2 2 2h12v-2H7.42c-.14 0-.25-.11-.25-.25l.03-.12.9-1.63h7.45c.75 0 1.41-.41 1.75-1.03l3.58-6.49c.08-.14.12-.31.12-.48 0-.55-.45-1-1-1H5.21l-.94-2H1zm16 16c-1.1 0-1.99.9-1.99 2s.89 2 1.99 2 2-.9 2-2-.9-2-2-2z"/>
        </svg>
      </button>
    </div>
  </header>
`;

// Component: Hero / Editorial
const Hero = () => `
  <section id="editorial" class="hero" aria-labelledby="hero-heading">
    <div class="hero-content">
      <h2 id="hero-heading" class="hero-title">The Midnight Collection</h2>
      <p class="hero-text">Discover our new line of premium dark aesthetics. Designed for the modern minimalist who thrives after dark.</p>
      <a href="#featured" class="btn-primary">Shop the Collection</a>
    </div>
    <div class="hero-image" role="img" aria-label="A sleek, dark-themed workspace setup"></div>
  </section>
`;

// Component: ProductCard
const ProductCard = ({ id, name, price, originalPrice, image, alt, badge }) => `
  <article class="product-card">
    <div class="product-img-wrapper">
      ${badge ? '<span class="badge">' + badge + '</span>' : ''}
      <img src="${image}" alt="${alt}" class="product-img" loading="lazy" />
    </div>
    <div class="product-info">
      <h3 class="product-name" id="product-${id}">${name}</h3>
      <div class="product-price-container">
        ${originalPrice ? `
          <span class="visually-hidden">Original price:</span>
          <s class="original-price">${originalPrice}</s>
        ` : ''}
        <span class="visually-hidden">Current price:</span>
        <span class="current-price">${price}</span>
      </div>
      <button class="btn-add-cart" aria-describedby="product-${id}">Add to Cart</button>
    </div>
  </article>
`;

// Component: FeaturedProducts
const FeaturedProducts = () => {
  const products = [
    {
      id: 'p1',
      name: 'Obsidian Keyboard',
      price: '$129.99',
      image: 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&q=80&w=400',
      alt: 'Mechanical keyboard with dark grey keys and subtle white backlighting'
    },
    {
      id: 'p2',
      name: 'Matte Black Mouse',
      price: '$79.99',
      image: 'https://images.unsplash.com/photo-1527814050087-379381547969?auto=format&fit=crop&q=80&w=400',
      alt: 'Ergonomic wireless mouse in matte black finish'
    },
    {
      id: 'p3',
      name: 'Eclipse Desk Mat',
      price: '$34.99',
      image: 'https://images.unsplash.com/photo-1616423640778-28d1b53229bd?auto=format&fit=crop&q=80&w=400',
      alt: 'Large black desk mat with minimal texture'
    },
    {
      id: 'p4',
      name: 'Onyx Headstand',
      price: '$49.99',
      image: 'https://images.unsplash.com/photo-1583394838336-acd977736f90?auto=format&fit=crop&q=80&w=400',
      alt: 'Sleek dark metal headphone stand'
    }
  ];

  return `
    <section id="featured" aria-labelledby="featured-heading">
      <h2 id="featured-heading" class="section-title">Featured Products</h2>
      <div class="product-grid">
        ${products.map(p => ProductCard(p)).join('')}
      </div>
    </section>
  `;
};

// Component: Deals
const Deals = () => {
  const products = [
    {
      id: 'd1',
      name: 'Shadow Monitor Arm',
      price: '$89.99',
      originalPrice: '$129.99',
      badge: 'Sale',
      image: 'https://images.unsplash.com/photo-1542393545-10f5cde2c810?auto=format&fit=crop&q=80&w=400',
      alt: 'Heavy duty black monitor arm attached to desk'
    },
    {
      id: 'd2',
      name: 'Void Desk Lamp',
      price: '$45.00',
      originalPrice: '$75.00',
      badge: '40% Off',
      image: 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&q=80&w=400',
      alt: 'Modern minimalist desk lamp casting warm light'
    }
  ];

  return \`
    <section id="deals" aria-labelledby="deals-heading">
      <h2 id="deals-heading" class="section-title">Today's Deals</h2>
      <div class="product-grid">
        \${products.map(p => ProductCard(p)).join('')}
      </div>
    </section>
  \`;
};

// Component: Footer
const Footer = () => \`
  <footer class="site-footer">
    <p class="footer-text">&copy; \${new Date().getFullYear()} Aura Retail. All rights reserved.</p>
  </footer>
\`;

// Main App Render
const App = () => \`
  \${Header()}
  <main id="main-content" class="container">
    <h1 class="visually-hidden">Aura - Dark Mode Ecommerce Homepage</h1>
    \${Hero()}
    \${FeaturedProducts()}
    \${Deals()}
  </main>
  \${Footer()}
\`;

// Mount
document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('root');
