  --font-sans: 'Segoe UI', system-ui, -apple-system, sans-serif;
}

/* Reset and Base Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
}

/* Accessibility: Skip to main content */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--accent-color);
  color: var(--bg-primary);
  padding: var(--spacing-md);
  z-index: 1000;
  text-decoration: none;
  font-weight: bold;
}
.skip-link:focus {
  top: 0;
}

/* Accessibility: Visually Hidden */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Accessibility: Focus Visible */
*:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 4px;
}

/* Header & Nav */
.site-header {
  background-color: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-md) var(--spacing-lg);
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  letter-spacing: 2px;
  color: var(--text-primary);
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  list-style: none;
  gap: var(--spacing-lg);
}

.main-nav a {
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.2s;
}

.main-nav a:hover {
  color: var(--accent-color);
}

.cart-btn {
  background: transparent;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.cart-btn:hover {
  color: var(--accent-color);
}
.cart-icon {
  width: 24px;
  height: 24px;
  fill: currentColor;
}

/* Main Content Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing-xl) var(--spacing-lg);
}

section {
  margin-bottom: var(--spacing-xl);
}

.section-title {
  font-size: 2rem;
  margin-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: var(--spacing-sm);
}

/* Editorial / Hero */
.hero {
  background-color: var(--bg-secondary);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  margin-bottom: var(--spacing-xl);
}
@media (min-width: 768px) {
  .hero {
    flex-direction: row;
  }
}
.hero-content {
  padding: var(--spacing-xl);
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hero-title {
  font-size: 2.5rem;
  margin-bottom: var(--spacing-md);
  line-height: 1.2;
}
.hero-text {
  font-size: 1.125rem;
  color: var(--text-secondary);
  margin-bottom: var(--spacing-lg);
}
.btn-primary {
  display: inline-block;
  background-color: var(--accent-color);
  color: var(--bg-primary);
  padding: 0.75rem 1.5rem;
  text-decoration: none;
  font-weight: bold;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  transition: background-color 0.2s;
  text-align: center;
  align-self: flex-start;
}
.btn-primary:hover {
  background-color: var(--accent-hover);
}
.hero-image {
  flex: 1;
  min-height: 300px;
  background-color: var(--bg-tertiary);
  background-image: url('https://images.unsplash.com/photo-1555529771-835f59bfc50c?auto=format&fit=crop&q=80&w=800');
  background-size: cover;
  background-position: center;
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

/* Product Card */
.product-card {
  background-color: var(--bg-secondary);
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s;
}
.product-card:hover {
  transform: translateY(-4px);
}
.product-img-wrapper {
  position: relative;
  aspect-ratio: 1 / 1;
  background-color: var(--bg-tertiary);
}
.product-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.badge {
  position: absolute;
  top: var(--spacing-md);
  right: var(--spacing-md);
  background-color: var(--danger-color);
  color: #000;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  font-weight: bold;
  border-radius: 4px;
}
.product-info {
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  flex: 1;
}
.product-name {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-sm);
}
.product-price-container {
  margin-bottom: var(--spacing-md);
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}
.current-price {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--accent-color);
}
.original-price {
  color: var(--text-secondary);
  text-decoration: line-through;
  font-size: 0.875rem;
}
.btn-add-cart {
  margin-top: auto;
  width: 100%;
  background-color: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 0.75rem;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
  transition: all 0.2s;
}
.btn-add-cart:hover {
  background-color: var(--border-color);
}

/* Footer */
.site-footer {
  background-color: var(--bg-secondary);
  padding: var(--spacing-xl) var(--spacing-lg);
  text-align: center;
  border-top: 1px solid var(--border-color);
  margin-top: auto;
}
.footer-text {
  color: var(--text-secondary);
  font-size: 0.875rem;
}    </style>
</head>
<body>
    <div id="root"></div>
    <script>
// Component: Header
